INSERT INTO CONTENTS (ENG,VI,START_TIME,END_TIME,VOLUME_SLUG) VALUES
	/* (UUID(),'4000-essential-english-words-1-26','Archie and his donkey','Archie và con lừa','4000_ESSENTIAL_ENGLISH_WORDS_1_26.mp3',NULL,'00:00:00.000','00:02:00.700','4000-essential-english-words-1',0,0,26) */
	('Old Archie needed some money','Ông già Archie cần ít tiền','00:00:03.000','00:00:05.400','4000-essential-english-words-1-26'),
	('He decided to sell his donkey','Ông quyết định bán con lừa của mình đi','00:00:05.400','00:00:07.800','4000-essential-english-words-1-26'),
	('So he and his son Tom went to town','Ông và con trai là Tom đi tới thị trấn','00:00:07.800','00:00:10.500','4000-essential-english-words-1-26'),
	('It was situated many miles away','Nơi đó nằm cách xa nhiều dặm','00:00:10.500','00:00:13.400','4000-essential-english-words-1-26'),
	('Soon, they met a woman','Chẳng bao lâu, họ gặp một người phụ nữ','00:00:13.400','00:00:15.800','4000-essential-english-words-1-26'),
	('"Where are you going?" she asked','"Hai người đi đâu vậy?" bà ta hỏi','00:00:15.800','00:00:18.800','4000-essential-english-words-1-26'),
	('"To town," said Archie','"Đến thị trấn," Archie trả lời','00:00:18.800','00:00:20.800','4000-essential-english-words-1-26'),
	('"Any smart person would ride the donkey," she said','"Ai thông minh cũng sẽ cưỡi lên con lừa," bà ta nói','00:00:20.800','00:00:24.800','4000-essential-english-words-1-26'),
	('"What are you implying?" Archie asked','"Bà đang ám chỉ điều gì vậy?" Archie hỏi','00:00:24.800','00:00:27.800','4000-essential-english-words-1-26'),
	('"I\'m very smart"','"Tôi là người thông minh"','00:00:27.800','00:00:29.800','4000-essential-english-words-1-26'),
	('Archie wanted to look smart','Archie muốn mình trông thật thông minh','00:00:29.800','00:00:31.800','4000-essential-english-words-1-26'),
	('So he climbed onto the donkey','Nên ông ta đã trèo lên lưng con lừa','00:00:31.800','00:00:33.800','4000-essential-english-words-1-26'),
	('Then they continued in the direction of the town',' Sau đó họ tiếp tục thẳng tiến đến thị trấn','00:00:33.800','00:00:36.800','4000-essential-english-words-1-26'),
	('Further along the road, they met a farmer','Đi được quãng đường xa hơn, họ gặp một người nông dân','00:00:36.800','00:00:40.300','4000-essential-english-words-1-26'),
	('"Hello," said Archie','"Xin chào," Archie nói','00:00:40.300','00:00:41.800','4000-essential-english-words-1-26'),
	('"We want to sell this donkey"','"Chúng tôi muốn bán con lừa này"','00:00:41.800','00:00:44.400','4000-essential-english-words-1-26'),
	('"Do you want to buy it?"','"Ông có muốn mua không?"','00:00:44.400','00:00:45.800','4000-essential-english-words-1-26'),
	('"I don\'t need a donkey," said the farmer','"Tôi không muốn mua lừa," người nông dân nói','00:00:45.800','00:00:49.000','4000-essential-english-words-1-26'),
	('"But if you want my advice, don\'t ride it"','"Nhưng nếu ông muốn một lời khuyên của tôi, thì đừng cưỡi nó"','00:00:49.000','00:00:52.300','4000-essential-english-words-1-26'),
	('"The donkey needs to be in good physical condition"','"Con lừa cần có một thể trạng tốt"','00:00:52.300','00:00:55.400','4000-essential-english-words-1-26'),
	('"Good idea," said Archie','"Ý kiến hay," Archie nói','00:00:55.400','00:00:57.800','4000-essential-english-words-1-26'),
	('"Tom, I want you to ride it"','"Tom, bố muốn con cưỡi nó"','00:00:57.800','00:00:59.800','4000-essential-english-words-1-26'),
	('"You\'re lighter"','Con nhẹ hơn bố','00:00:59.800','00:01:01.000','4000-essential-english-words-1-26'),
	('"Neither you nor your son should ride it"','"Ông và con trai đều không nên cưỡi nó"','00:01:01.000','00:01:04.300','4000-essential-english-words-1-26'),
	('"It looks very tired"','"Nó trông có vẻ rất mệt"','00:01:04.300','00:01:06.000','4000-essential-english-words-1-26'),
	('"You should carry the donkey" suggested the farmer','"Ông nên ôm con lừa đi." người nông dân gợi ý','00:01:06.000','00:01:09.900','4000-essential-english-words-1-26'),
	('"You\'re right," said Archie','"Ông nói đúng," Archie nói','00:01:09.900','00:01:11.900','4000-essential-english-words-1-26'),
	('"Come on, Tom"','"Lại đây nào, Tom"','00:01:11.900','00:01:13.300','4000-essential-english-words-1-26'),
	('"We\'ll carry it for the final few miles"','"Chúng ta sẽ ôm nó cho đến những dặm cuối cùng"','00:01:13.300','00:01:15.800','4000-essential-english-words-1-26'),
	('"The donkey was very heavy, and they couldn\'t maintain a good speed"','"Con lừa rất nặng, và họ không thể duy trì tốc độ nhanh được"','00:01:15.800','00:01:20.200','4000-essential-english-words-1-26'),
	('They didn\'t arrive until late in the evening','Họ không thể đến được thị trấn cho đến khi trời đã khuya','00:01:20.200','00:01:22.800','4000-essential-english-words-1-26'),
	('At last, they walked into the town','Cuối cùng, họ đã đi tới được thị trấn','00:01:22.800','00:01:25.800','4000-essential-english-words-1-26'),
	('But there they attracted the attention of some teenage boys','Nhưng ở đó họ lại bị thu hút bởi những thiếu niên','00:01:25.800','00:01:29.700','4000-essential-english-words-1-26'),
	('They laughed at Tom and Archie','Chúng cười nhạo Tom và Archie','00:01:29.700','00:01:31.700','4000-essential-english-words-1-26'),
	('They started to throw stones at them','Chúng bắt đầu ném đá vào họ','00:01:31.700','00:01:33.800','4000-essential-english-words-1-26'),
	('The donkey reacted by kicking','Con lừa phản ứng bằng việc đá loạn xạ','00:01:33.800','00:01:36.200','4000-essential-english-words-1-26'),
	('Tom and Archie dropped the donkey','Tom và Archie thả con lừa ra','00:01:36.200','00:01:39.100','4000-essential-english-words-1-26'),
	('It fell on the ground and then ran away','Nó ngã trên đất và bỏ chạy','00:01:39.100','00:01:41.900','4000-essential-english-words-1-26'),
	('Archie lost his donkey','Archie mất con lừa','00:01:41.900','00:01:43.900','4000-essential-english-words-1-26'),
	('He went home with no money','Ông quay về nhà nhưng trong tay không có đồng nào cả','00:01:43.900','00:01:46.700','4000-essential-english-words-1-26'),
	('What does this story teach us?','Câu chuyện này dạy chúng ta điều gì?','00:01:46.700','00:01:48.800','4000-essential-english-words-1-26'),
	('We cannot please everyone in our society','Chúng ta không thể làm hài lòng mọi người trong xã hội','00:01:48.800','00:01:51.900','4000-essential-english-words-1-26'),
	('Don\'t take everyone\'s advice, but set your own standards','Đừng nghe tất cả lời khuyên của mọi người, nhưng cần đặt cho riêng mình những tiêu chuẩn','00:01:51.900','00:01:56.900','4000-essential-english-words-1-26'),
	('Prove to everyone that you can make decisions by yoursel','Chứng minh cho mọi người rằng bạn có thể đưa ra quyết định của chính mình','00:01:56.900','00:02:00.700','4000-essential-english-words-1-26'),
	('Otherwise, you may end up with nothing at all','Nếu không bạn có thể kết thúc cuộc đời mình với việc chẳng còn gì cả','00:02:00.700','00:02:04.200','4000-essential-english-words-1-26'),

	/* (UUID(),'4000-essential-english-words-1-27','The spider and the bird','Con nhện và con chim','4000_ESSENTIAL_ENGLISH_WORDS_1_27.mp3',NULL,'00:00:00.000','00:02:02.000','4000-essential-english-words-1',0,0,27) */
	('There was once a very big spider','Thuở xưa có một chú nhện rất lớn','00:00:03.400','00:00:06.300','4000-essential-english-words-1-27'),
	('If a bug got into his web, he would examine it','Nếu một con bọ bị rơi vào mạng nhện của chú, chú sẽ cân nhắc','00:00:06.300','00:00:10.100','4000-essential-english-words-1-27'),
	('However, he didn\'t eat the bug right away','Nhưng chú không ăn con bọ ngay','00:00:10.100','00:00:13.800','4000-essential-english-words-1-27'),
	('He asked the bug a question first','Trước hết, chú sẽ hỏi con bọ đó một câu hỏi','00:00:13.800','00:00:16.800','4000-essential-english-words-1-27'),
	('It was always quite a difficult puzzle','Đó luôn là một câu đố khá khó','00:00:16.800','00:00:19.700','4000-essential-english-words-1-27'),
	('If the bug\'s answer was correct, he let it go','Nếu câu trả lời của con bọ đúng thì chú sẽ thả nó đi','00:00:19.700','00:00:23.600','4000-essential-english-words-1-27'),
	('If not, he ate it','Còn nếu không thì chú sẽ ăn nó','00:00:23.600','00:00:24.800','4000-essential-english-words-1-27'),
	('One day, a small bird on a journey flew into the spider\'s web','Một ngày nọ, một cô chim nhỏ đang trên hành trình của mình thì bị sa vào mạng nhện','00:00:24.800','00:00:30.500','4000-essential-english-words-1-27'),
	('The spider couldn\'t imagine eating a bird','Chú nhện không thể tưởng tượng đến việc ăn một con chim','00:00:30.500','00:00:33.600','4000-essential-english-words-1-27'),
	('It was so big','Nó thật là lớn','00:00:33.600','00:00:34.800','4000-essential-english-words-1-27'),
	('But his hunger was too great','Nhưng chú đang trong cơn đói','00:00:34.800','00:00:37.600','4000-essential-english-words-1-27'),
	('He said to the bird, "If you cannot give me a specific answer, I will eat you"','Chú nói với cô chim rằng "Nếu ngươi không cho ta câu trả lời chính xác, ta sẽ ăn ngươi"','00:00:37.600','00:00:42.800','4000-essential-english-words-1-27'),
	('The bird laughed','Cô chim liền cười lớn','00:00:42.800','00:00:44.300','4000-essential-english-words-1-27'),
	('"I could eat you"','"Ta cũng có thể thể ăn ngươi đấy"','00:00:44.300','00:00:45.800','4000-essential-english-words-1-27'),
	('But the bird was actually scared','Nhưng thực ra cô chim rất sợ hãi','00:00:45.800','00:00:48.800','4000-essential-english-words-1-27'),
	('She had used all her energy trying to get out of the web','Cô dùng hết sức mình để cố gắng thoát ra khỏi mạng nhện','00:00:48.800','00:00:52.500','4000-essential-english-words-1-27'),
	('And a spider\'s bite can be very effective in killing animals','Và một vết cắn của con nhện có thể giết chết một con vật','00:00:52.500','00:00:57.200','4000-essential-english-words-1-27'),
	('"Please don\'t eat me," the bird said','"Làm ơn đừng ăn tôi," cô chim nói','00:00:57.200','00:00:59.800','4000-essential-english-words-1-27'),
	('"I would rather make a deal with you"','"Tôi muốn thỏa thuận với anh"','00:00:59.800','00:01:01.800','4000-essential-english-words-1-27'),
	('"OK," the spider said','"Được thôi," chú nhện nói','00:01:01.800','00:01:04.200','4000-essential-english-words-1-27'),
	('"If your answer is right, I will let you go"','"Nếu câu trả lời của ngươi đúng, ta sẽ để ngươi đi"','00:01:04.200','00:01:07.500','4000-essential-english-words-1-27'),
	('"If not, you must give me a gift"','"Nếu không, ngươi phải đưa ta một món quà"','00:01:07.500','00:01:09.800','4000-essential-english-words-1-27'),
	('"It must be something of great value"','"Nó phải là thứ có giá trị"','00:01:09.800','00:01:12.800','4000-essential-english-words-1-27'),
	('The bird said, "You can pick anything you want to eat"','Cô chim nói, "Anh có thể đề nghị bất cứ thứ gì anh muốn ăn"','00:01:12.800','00:01:16.300','4000-essential-english-words-1-27'),
	('"I will find it for you"','"Tôi sẽ đi kiếm cho anh"','00:01:16.300','00:01:18.300','4000-essential-english-words-1-27'),
	('The spider agreed','Chú nhện đồng ý','00:01:18.300','00:01:20.000','4000-essential-english-words-1-27'),
	('"Where can you take a trip to the coast, the desert, and the mountains at the same time?" the spider asked','"Nơi nào mà ngươi có thể thực hiện chuyến đi đến cả bờ biển, sa mạc, và núi cùng một lúc?" chú nhện hỏi','00:01:20.000','00:01:26.800','4000-essential-english-words-1-27'),
	('The bird asked, "Does this place have earthquakes?"','Cô chim hỏi lại: "Đấy chẳng phải nơi có động đất hay sao?"','00:01:26.800','00:01:30.300','4000-essential-english-words-1-27'),
	('But the spider did not say anything','Nhưng chú nhện không nói nói gì cả','00:01:30.300','00:01:32.800','4000-essential-english-words-1-27'),
	('"I can see those places when I fly"','"Tôi có thể nhìn thấy những nơi này khi tôi bay"','00:01:32.800','00:01:35.800','4000-essential-english-words-1-27'),
	('"Is the \'sky\' the right answer?"','"\'Bầu trời\' có phải đáp án đúng không?"','00:01:35.800','00:01:37.800','4000-essential-english-words-1-27'),
	('"False" said the spider','"Sai" chú nhện nói','00:01:37.800','00:01:40.200','4000-essential-english-words-1-27'),
	('"The answer is Hawaii"','"Đáp án là Hawaii"','00:01:40.200','00:01:41.900','4000-essential-english-words-1-27'),
	('"Now you must find some bugs for me"','"Giờ ngươi phải đi tìm cho ta mấy con bọ"','00:01:41.900','00:01:44.900','4000-essential-english-words-1-27'),
	('The spider climbed on the bird\'s back','Chú nhện leo lên lưng con chim','00:01:44.900','00:01:47.800','4000-essential-english-words-1-27'),
	('They flew and ate bugs together','Họ bay và cùng nhau ăn những con bọ','00:01:47.800','00:01:50.200','4000-essential-english-words-1-27'),
	('They took a tour of the forest','Họ đi một vòng quanh khu rừng','00:01:50.200','00:01:52.800','4000-essential-english-words-1-27'),
	('Then the bird took the spider home','Rồi chim đưa nhện về nhà','00:01:52.800','00:01:55.800','4000-essential-english-words-1-27'),
	('From that day on, they were friends','Từ hôm đó trở đi họ là bạn','00:01:55.800','00:01:58.800','4000-essential-english-words-1-27'),
	('And they never tried to eat each other again','Và họ không bao giờ cố gắng ăn thịt nhau lần nữa','00:01:58.800','00:02:02.000','4000-essential-english-words-1-27'),

	/* (UUID(),'4000-essential-english-words-1-28','The party','Bữa tiệc sinh nhật','4000_ESSENTIAL_ENGLISH_WORDS_1_28.mp3',NULL,'00:00:00.000','00:02:11.000','4000-essential-english-words-1',0,0,28) */
	('Cody\'s family moved to a new house','Gia đình của Cody vừa mới chuyển tới ở một ngôi nhà mới','00:00:03.000','00:00:05.000','4000-essential-english-words-1-28'),
	('His dad got a new job as a professor','Cha cậu cũng đã bắt đầu một công việc mới là một giáo sư','00:00:05.000','00:00:07.800','4000-essential-english-words-1-28'),
	('Cody liked his new town, but he missed his grandparents','Cody thích thị trấn mới này thế nhưng cậu bé lại rất nhớ ông bà','00:00:07.800','00:00:11.800','4000-essential-english-words-1-28'),
	('For his birthday, Cody wanted to have a party','Cody muốn có một bữa tiệc trong ngày sinh nhật của mình','00:00:11.800','00:00:15.000','4000-essential-english-words-1-28'),
	('His dad said, "Yes, we could even have a band play"','Cha cậu bé nói rằng: "Được thôi, chúng ta thậm chí mời cả ban nhạc đến biểu diễn nữa cơ"','00:00:15.000','00:00:19.500','4000-essential-english-words-1-28'),
	('On the day of the party, Cody woke up and rushed to get ready','Vào ngày sinh nhật, Cody thức dậy rồi vội vã chuẩn bị mọi thứ','00:00:19.500','00:00:23.600','4000-essential-english-words-1-28'),
	('He started to check his list of things to do','Cậu bé bắt đầu kiểm tra danh sách những việc cần làm','00:00:23.600','00:00:26.600','4000-essential-english-words-1-28'),
	('He was so excited','Cậu bé vô cùng hào hứng','00:00:26.600','00:00:28.600','4000-essential-english-words-1-28'),
	('But then he noticed something terrible','Nhưng sau đó Cody nhận thấy có điều gì đó rất tệ','00:00:28.600','00:00:30.800','4000-essential-english-words-1-28'),
	('There was snow on the ground and lots of it','Ở ngoài sân có rất nhiều tuyết','00:00:30.800','00:00:34.700','4000-essential-english-words-1-28'),
	('"Dad" he yelled','"Cha ơi", cậu hét toáng lên','00:00:34.700','00:00:36.800','4000-essential-english-words-1-28'),
	('"How can the band play their instruments outside?"','"Làm sao mà ban nhạc có thể biểu diễn nhạc cụ ở bên ngoài đây"','00:00:36.800','00:00:40.200','4000-essential-english-words-1-28'),
	('Dad said, "We\'ll move the stage inside"','Cha cậu đáp: "Chúng ta sẽ chuyển sân khấu vào trong"','00:00:40.200','00:00:43.800','4000-essential-english-words-1-28'),
	('It barely fit within the garage because there were some boxes and garbage there','Rất khó để chuyển vào trong gara vì có một vài cái hộp và túi rác ở đó','00:00:43.800','00:00:48.800','4000-essential-english-words-1-28'),
	('But when they finished, they got a call from the band','Nhưng khi hai ba con Cody thu xếp xong xuôi thì họ nhận được cuộc gọi từ ban nhạc','00:00:48.800','00:00:52.100','4000-essential-english-words-1-28'),
	('They did not want to come in the snow storm','Họ nói rằng họ không thể đến vì đang có bão tuyết','00:00:52.100','00:00:54.800','4000-essential-english-words-1-28'),
	('Dad said, "Let\'s get someone to perform magic"','Cha cậu nói, "Vậy chúng ta sẽ tìm ai đó trình diễn ảo thuật nhé"','00:00:54.800','00:00:58.800','4000-essential-english-words-1-28'),
	('But no one would come because of the snow','Nhưng không ai có thể đến được vì tuyết rơi rất dày','00:00:58.800','00:01:01.900','4000-essential-english-words-1-28'),
	('Finally, Dad said, "Cody, there\'s too much snow"','Cuối cùng cha cậu nói, "Cody à, tuyết rơi nhiều quá"','00:01:01.900','00:01:05.900','4000-essential-english-words-1-28'),
	('"We need to cancel the party"','"Chúng ta cần phải hủy bữa tiệc thôi"','00:01:05.900','00:01:08.000','4000-essential-english-words-1-28'),
	('"Yes, sir," Cody said sadly','"Dạ vâng, thưa cha," Cody nói một cách buồn bã','00:01:08.000','00:01:11.000','4000-essential-english-words-1-28'),
	('"It\'s going to be a boring birthday," he predicted','"Chắc hôm nay sẽ là môt ngày sinh nhật buồn chán lắm đây," cậu nghĩ','00:01:11.000','00:01:15.000','4000-essential-english-words-1-28'),
	('Cody wanted to share his birthday with someone','Cody muốn cùng chia sẻ ngày sinh nhật của mình với ai đó','00:01:15.000','00:01:17.900','4000-essential-english-words-1-28'),
	('He wanted to be at his old home','Cậu muốn ở ngôi nhà cũ trước đây','00:01:17.900','00:01:20.400','4000-essential-english-words-1-28'),
	('He wanted to see his grandparents','Cậu muốn được gặp ông bà yêu quý của mình','00:01:20.400','00:01:22.800','4000-essential-english-words-1-28'),
	('But then something got his attention','Thế rồi có thứ gì đó đã thu hút sự chú ý của cậu bé','00:01:22.800','00:01:24.800','4000-essential-english-words-1-28'),
	('He noticed a car in the driveway','Cody thấy có một chiếc xe ô tô đậu ở lối vào','00:01:24.800','00:01:27.800','4000-essential-english-words-1-28'),
	('His grandparents owned a car like that','Chiếc xe này giống y như chiếc xe của ông bà vậy','00:01:27.800','00:01:30.800','4000-essential-english-words-1-28'),
	('Cody was right','Cody đã đúng','00:01:30.800','00:01:32.500','4000-essential-english-words-1-28'),
	('His grandparents came for his birthday','Ông bà đến dự tiệc sinh nhật của cậu','00:01:32.500','00:01:35.200','4000-essential-english-words-1-28'),
	('"Happy birthday, Cody"','"Sinh nhật vui vẻ nhé Cody"','00:01:35.200','00:01:36.800','4000-essential-english-words-1-28'),
	('"We\'re sorry we are late"','"Chúng ta xin lỗi vì đã đến muộn"','00:01:36.800','00:01:38.800','4000-essential-english-words-1-28'),
	('"But there was so much snow"','"Tuyết rơi dày quá mà"','00:01:38.800','00:01:40.800','4000-essential-english-words-1-28'),
	('"It made us go off schedule"','"Tuyết khiến ông bà đến trễ vào bữa tiệc sinh nhật của cháu"','00:01:40.800','00:01:42.800','4000-essential-english-words-1-28'),
	('"We tried to leave a message to tell you"','"Chúng ta đã cố gắng để lại một tin nhắn cho cháu"','00:01:42.800','00:01:45.800','4000-essential-english-words-1-28'),
	('Cody told them what happened','Cody kể cho ông bà những chuyện đã xảy ra','00:01:45.800','00:01:47.800','4000-essential-english-words-1-28'),
	('"I\'m sorry," said Grandpa','"Ông thấy rất tiếc," ông cậu bé nói','00:01:47.800','00:01:50.400','4000-essential-english-words-1-28'),
	('"I was sad," Cody said','"Con rất buồn ông à," Cody nois','00:01:50.400','00:01:52.800','4000-essential-english-words-1-28'),
	('"But I\'m not anymore"','Nhưng giờ thì hết rồi','00:01:52.800','00:01:54.800','4000-essential-english-words-1-28'),
	('"I\'m so happy to see you"','"Con rất vui vì được gặp mọi người"','00:01:54.800','00:01:57.000','4000-essential-english-words-1-28'),
	('Dad brought out Cody\'s birthday treat','Bố mang bánh sinh nhật của Cody ra','00:01:57.000','00:01:59.800','4000-essential-english-words-1-28'),
	('It was his favorite type, a sundae with whipped cream on top','Chiếc bánh đúng khẩu vị yêu thích của cậu bé, một chiếc bánh vị hoa quả với lớp kem xốp béo ngậy ở bên trên','00:01:59.800','00:02:04.500','4000-essential-english-words-1-28'),
	('Then Cody told his grandparents about the new town','Rồi Cody ngồi kể cho ông bà nghe về thị trấn mới','00:02:04.500','00:02:07.800','4000-essential-english-words-1-28'),
	('It was his best birthday ever','Đó thật sự là một ngày sinh nhật tuyệt vời nhất của cậu bé','00:02:07.800','00:02:11.000','4000-essential-english-words-1-28'),

	/* (UUID(),'4000-essential-english-words-1-29','How the World got light','Thế giới đã có ánh sáng như thế nào','4000_ESSENTIAL_ENGLISH_WORDS_1_29.mp3',NULL,'00:00:00.000','00:02:03.800','4000-essential-english-words-1',0,0,29) */
	('The president of Darkland was a pig - a very bad pig','Lãnh chúa của Vùng đất bóng tối là một con lợn - một con lợn cực kỳ xấu tính','00:00:03.800','00:00:08.500','4000-essential-english-words-1-29'),
	('He was a pig of major importance','Hắn là một con lợn quan trọng chủ chốt','00:00:08.500','00:00:11.500','4000-essential-english-words-1-29'),
	('He was rich, and he had a lot of strength','Hắn rất giàu, và có nhiều sức khỏe','00:00:11.500','00:00:14.800','4000-essential-english-words-1-29'),
	('But he was mean to all the animals in Darkland','Nhưng hắn hèn mọn với muôn thú ở Vùng đất bóng tối','00:00:14.800','00:00:18.800','4000-essential-english-words-1-29'),
	('He kept all of the world\'s light in a bag','Hắn giữ ánh sáng của cả thế giới trong một cái túi','00:00:18.800','00:00:22.300','4000-essential-english-words-1-29'),
	('He preferred to keep the world cool and dark','Hắn thích giữ thế giới mát mẻ và tăm tối','00:00:22.300','00:00:25.500','4000-essential-english-words-1-29'),
	('He wanted to stop the progress of the city','Hắn muốn dừng tiến trình của thành phố lại','00:00:25.500','00:00:28.700','4000-essential-english-words-1-29'),
	('The animals couldn\'t work in the dark','Muông thú không thể làm việc trong bóng tối','00:00:28.700','00:00:31.000','4000-essential-english-words-1-29'),
	('He didn\'t have any respect for them','Hắn không có bất cứ tôn trọng nào dành cho họ cả','00:00:31.000','00:00:33.700','4000-essential-english-words-1-29'),
	('"Light is too good for them," he said','"Anh sáng quá tốt cho họ," hắn nói','00:00:33.700','00:00:36.400','4000-essential-english-words-1-29'),
	('"Only I should have light"','"Chỉ mình tôi nên có ánh sáng thôi"','00:00:36.400','00:00:38.800','4000-essential-english-words-1-29'),
	('But the animals needed light','Nhưng muông thú cần ánh sáng','00:00:38.800','00:00:40.800','4000-essential-english-words-1-29'),
	('So they decided to hold a competition','Vì vậy họ quyết định tổ chức một cuộc thi','00:00:40.800','00:00:43.800','4000-essential-english-words-1-29'),
	('They wanted to find the smartest animal in Darkland','Họ muốn tìm ra con vật thông minh nhất ở Vùng đất bóng tối','00:00:43.800','00:00:47.300','4000-essential-english-words-1-29'),
	('That animal had to steal light from the president','Con vật đó sẽ phải ăn trộm ánh sáng từ chủ tịch','00:00:47.300','00:00:51.100','4000-essential-english-words-1-29'),
	('They advertised the competition everywhere','Chúng quảng bá cuộc thi khắp mọi nơi','00:00:51.100','00:00:54.300','4000-essential-english-words-1-29'),
	('All the animals came','Muông thú đều đến','00:00:54.300','00:00:56.900','4000-essential-english-words-1-29'),
	('The animals all showed off their skills','Các con vật đều thể hiện hết kỹ năng của mình','00:00:56.900','00:01:00.000','4000-essential-english-words-1-29'),
	('The audience watched and then voted for the animal with the most knowledge',' Khán giả xem và bình chọn cho con vật có trí thông minh nhất','00:01:00.000','00:01:05.000','4000-essential-english-words-1-29'),
	('The winner was a tall bird named Raven','Con vật chiến thắng là một chú chim cao lớn tên Raven','00:01:05.000','00:01:08.700','4000-essential-english-words-1-29'),
	('They assigned him the job of getting light','Chúng phân công cho anh công việc lấy lại ánh sáng','00:01:08.700','00:01:11.800','4000-essential-english-words-1-29'),
	('The next morning, Raven ate breakfast and then left his home','Sáng hôm sau, Raven ăn bữa sáng và rời nhà mình','00:01:11.800','00:01:15.800','4000-essential-english-words-1-29'),
	('"How will I gain light from the president?" thought Raven','"Làm sao để mình có thể đạt được ánh sáng từ chủ tịch?" Raven nghĩ','00:01:15.800','00:01:20.000','4000-essential-english-words-1-29'),
	('He needed to trick the president somehow','Anh ấy cần phải lừa lãnh chúa bằng cách nào đó','00:01:20.000','00:01:23.000','4000-essential-english-words-1-29'),
	('Then, Raven had an idea','Rồi, Raven nghĩ ra một ý tưởng','00:01:23.000','00:01:26.000','4000-essential-english-words-1-29'),
	('Raven could make his voice sound like anything','Raven có thể khiến giọng của bản thân giống bất cứ thứ gì','00:01:26.000','00:01:29.000','4000-essential-english-words-1-29'),
	('Raven walked up to the president\'s door','Raven đi bộ lên cửa của lãnh chúa','00:01:29.000','00:01:31.800','4000-essential-english-words-1-29'),
	('He made the sound of a crying baby','Anh tạo nên âm thanh của một đứa bé đang khóc','00:01:31.800','00:01:34.800','4000-essential-english-words-1-29'),
	('He cried very loudly','Anh ấy khóc rất to','00:01:34.800','00:01:36.800','4000-essential-english-words-1-29'),
	('Soon, the president opened the door','Không lâu sau, lãnh chúa ra mở cửa','00:01:36.800','00:01:40.300','4000-essential-english-words-1-29'),
	('"Be quiet" the president yelled','"Im lặng đi" lãnh chúa quát','00:01:40.300','00:01:43.100','4000-essential-english-words-1-29'),
	('Right then, Raven quickly made his move','Ngay lúc đó, Raven nhanh chóng hành động','00:01:43.100','00:01:46.000','4000-essential-english-words-1-29'),
	('He flew by the pig and found the soft bag','Anh ấy bay qua con lợn và tìm thấy chiếc túi mềm','00:01:46.000','00:01:49.500','4000-essential-english-words-1-29'),
	('He took it outside','Anh ấy lấy nó ra','00:01:49.500','00:01:50.800','4000-essential-english-words-1-29'),
	('The sun was inside the bag','Mặt trời đang ở trong chiếc túi đó','00:01:50.800','00:01:53.000','4000-essential-english-words-1-29'),
	('Raven flew high and put the sun in the sky','Raven bay cao và đặt chiếc túi trên bầu trời','00:01:53.000','00:01:56.900','4000-essential-english-words-1-29'),
	('The president was very mad','Lãnh chúa rất tức giận','00:01:56.900','00:01:59.000','4000-essential-english-words-1-29'),
	('Raven tricked him','Raven đã lừa hắn','00:01:59.000','00:02:01.800','4000-essential-english-words-1-29'),
	('But the other animals were very happy','Nhưng những động vật khác thì lại rất hạnh phúc','00:02:01.800','00:02:03.800','4000-essential-english-words-1-29'),
	('At last, they had light - all because of Raven\'s smart thinking','Cuối cùng, họ có ánh sáng - tất cả là nhờ suy nghĩ thông minh của Raven','00:02:03.800','00:02:09.300','4000-essential-english-words-1-29'),

	/* (UUID(),'4000-essential-english-words-1-30','Cats and secrets','Con mèo và những bí mật','4000_ESSENTIAL_ENGLISH_WORDS_1_30.mp3',NULL,'00:00:00.000','00:01:57.000','4000-essential-english-words-1',1,1,30) */
	('In English, there is a common idiom "let the cat out of the bag"','Trong tiếng Anh, có một thành ngữ phổ biến là "Thả mèo ra khỏi túi"','00:00:03.400','00:00:08.800','4000-essential-english-words-1-30'),
	('It means to tell a secret','Nó có nghĩa là tiết lộ một bí mật','00:00:08.800','00:00:10.900','4000-essential-english-words-1-30'),
	('But where did this idiom start?','Nhưng thành ngữ này bắt nguồn từ đâu?','00:00:10.700','00:00:12.900','4000-essential-english-words-1-30'),
	('It came from a section of England','Nó bắt nguồn từ một khu vực của nước Anh','00:00:12.900','00:00:15.400','4000-essential-english-words-1-30'),
	('Long ago, people there went from town to town to sell things like vegetables, clothes, and pigs','Ngày xưa, người dân ở đó đi từ thị trấn này sang thị trấn khác để bán những thứ như rau củ, quần áo và heo','00:00:15.400','00:00:22.400','4000-essential-english-words-1-30'),
	('They had strong beliefs about honesty','Họ có niềm tin mạnh mẽ (rất coi trọng) sự trung thực','00:00:22.400','00:00:24.900','4000-essential-english-words-1-30'),
	('They didn\'t like lying','Họ không thích nói dối','00:00:24.900','00:00:26.900','4000-essential-english-words-1-30'),
	('One day, a man went to the section\'s center to sell things','Một ngày nọ, một người đàn ông đến trung tâm của vùng đó để bán hàng','00:00:26.900','00:00:30.900','4000-essential-english-words-1-30'),
	('"I have a baby pig for sale. It won\'t cost much," he said','"Tôi có một con heo con để bán. Nó sẽ không đắt đâu," anh ta nói','00:00:30.900','00:00:35.900','4000-essential-english-words-1-30'),
	('He held the animal above his head','Anh ta giơ con vật lên trên đầu','00:00:35.900','00:00:38.000','4000-essential-english-words-1-30'),
	('His style was different from honest people\'s style','Cách làm của anh ta khác với những người trung thực','00:00:38.000','00:00:41.600','4000-essential-english-words-1-30'),
	('He was a master of tricking people and lying','Anh ta là bậc thầy trong việc lừa người và nói dối','00:00:41.600','00:00:44.300','4000-essential-english-words-1-30'),
	('A woman named Beth scanned his pig','Một người phụ nữ tên Beth quan sát con heo của anh ta','00:00:44.300','00:00:48.000','4000-essential-english-words-1-30'),
	('He offered her the pig for one gold coin','Anh ta đề nghị bán con heo cho cô với giá một đồng tiền vàng','00:00:48.000','00:00:51.000','4000-essential-english-words-1-30'),
	('That was a very small amount','Đó là một khoản tiền rất nhỏ','00:00:51.000','00:00:53.200','4000-essential-english-words-1-30'),
	('Beth gave him the coin','Beth đưa đồng tiền cho anh ta','00:00:53.200','00:00:55.200','4000-essential-english-words-1-30'),
	('He put it in his pocket','Anh ta bỏ nó vào túi','00:00:55.200','00:00:57.200','4000-essential-english-words-1-30'),
	('He walked ahead of Beth to get the pig','Anh ta đi trước Beth để lấy con heo','00:00:57.200','00:01:00.000','4000-essential-english-words-1-30'),
	('He gave her a closed bag and said, "Here\'s your pig"','Anh ta đưa cho cô một chiếc túi đóng kín và nói, "Con heo của cô đây"','00:01:00.000','00:01:04.000','4000-essential-english-words-1-30'),
	('He then left very quickly','Sau đó, anh ta rời đi rất vội vã','00:01:04.000','00:01:06.200','4000-essential-english-words-1-30'),
	('Beth looked at the bag\'s surface','Beth nhìn bề mặt chiếc túi','00:01:06.200','00:01:08.900','4000-essential-english-words-1-30'),
	('It was moving','Nó đang chuyển động','00:01:08.900','00:01:10.800','4000-essential-english-words-1-30'),
	('She opened it to let the pig out','Cô mở túi để thả con heo ra','00:01:10.800','00:01:12.900','4000-essential-english-words-1-30'),
	('A cat was inside','Bên trong là một con mèo','00:01:12.900','00:01:15.100','4000-essential-english-words-1-30'),
	('"He tricked me! That isn\'t proper," she said','"Anh ta đã lừa tôi! Điều đó không đúng," cô ấy nói','00:01:15.100','00:01:19.800','4000-essential-english-words-1-30'),
	('Later, the man returned to trick more people','Sau đó, người đàn ông quay lại để lừa thêm nhiều người','00:01:19.800','00:01:22.900','4000-essential-english-words-1-30'),
	('Beth saw him and the memory of the cat came back','Beth nhìn thấy anh ta và nhớ lại chuyện con mèo','00:01:22.900','00:01:26.700','4000-essential-english-words-1-30'),
	('She told her friends','Cô ấy kể cho bạn bè của mình','00:01:26.700','00:01:28.400','4000-essential-english-words-1-30'),
	('They stopped him','Họ chặn anh ta lại','00:01:28.400','00:01:29.800','4000-essential-english-words-1-30'),
	('But no one knew what to do next','Nhưng không ai biết phải làm gì tiếp theo','00:01:29.800','00:01:32.100','4000-essential-english-words-1-30'),
	('Someone said, "We need an independent and fair person to decide that"','Một người nói, "Chúng ta cần một người độc lập và công bằng để đưa ra phán quyết"','00:01:32.100','00:01:37.100','4000-essential-english-words-1-30'),
	('They went to the judge','Họ đến gặp quan tòa','00:01:37.100','00:01:38.800','4000-essential-english-words-1-30'),
	('Beth told him about the cat in the bag','Beth kể cho quan tòa nghe về con mèo trong túi','00:01:38.800','00:01:41.800','4000-essential-english-words-1-30'),
	('The judge asked, "Is there evidence?"','Quan tòa hỏi, "Có bằng chứng không?"','00:01:41.800','00:01:44.800','4000-essential-english-words-1-30'),
	('"Can you demonstrate how he did it?"','"Cô có thể chứng minh anh ta đã làm việc đó như thế nào không?"','00:01:44.800','00:01:47.600','4000-essential-english-words-1-30'),
	('"Look in his bag," said Beth','"Hãy nhìn vào túi của anh ta," Beth nói','00:01:47.600','00:01:50.000','4000-essential-english-words-1-30'),
	('She opened it and let a cat out of the bag','Cô mở túi ra và thả một con mèo ra ngoài','00:01:50.000','00:01:53.500','4000-essential-english-words-1-30'),
	('They learned the man\'s secret, and he went to jail','Mọi người biết được bí mật của người đàn ông, và anh ta đã đi tù','00:01:53.500','00:01:57.000','4000-essential-english-words-1-30'),
	('That\'s how the idiom "let the cat out of the bag" came to mean to tell a secret','Đó là cách thành ngữ "Thả mèo ra khỏi túi" mang nghĩa là tiết lộ một bí mật','00:01:57.000','00:02:03.000','4000-essential-english-words-1-30');
